import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.BvlN9b-o.js";const S=JSON.parse('{"title":"API 配置","description":"","frontmatter":{},"headers":[],"relativePath":"reference/config.md","filePath":"reference/config.md"}'),c={name:"reference/config.md"};function a(i,t,n,s,l,_){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="api-配置" tabindex="-1">API 配置 <a class="header-anchor" href="#api-配置" aria-label="Permalink to &quot;API 配置&quot;">​</a></h1><p>从 Settings 定义自动生成；生产秘密不进入文档。</p><table tabindex="0"><thead><tr><th>变量</th><th>默认值</th><th>敏感值</th><th>说明</th></tr></thead><tbody><tr><td><code>DATABASE_URL</code></td><td>必填</td><td>是</td><td>PostgreSQL connection URL. Required; never logged.</td></tr><tr><td><code>APP_BIND</code></td><td>127.0.0.1:3000</td><td>否</td><td>API listener IP address and port.</td></tr><tr><td><code>RUST_LOG</code></td><td>info</td><td>否</td><td>Structured log filter.</td></tr><tr><td><code>MIGRATION_TIMEOUT_SECS</code></td><td>30</td><td>否</td><td>Migration execution deadline in seconds (1..3600).</td></tr><tr><td><code>APP_ORIGIN</code></td><td><a href="http://127.0.0.1:5173" target="_blank" rel="noreferrer">http://127.0.0.1:5173</a></td><td>否</td><td>Trusted browser origin. HTTPS required except loopback development.</td></tr><tr><td><code>SESSION_ABSOLUTE_SECS</code></td><td>604800</td><td>否</td><td>Absolute session lifetime in seconds (60..2592000).</td></tr><tr><td><code>SESSION_IDLE_SECS</code></td><td>86400</td><td>否</td><td>Idle session lifetime in seconds (60..absolute lifetime).</td></tr><tr><td><code>S3_ENDPOINT</code></td><td>必填</td><td>否</td><td>Internal S3 endpoint at its root path. Unset disables object storage.</td></tr><tr><td><code>S3_PUBLIC_ENDPOINT</code></td><td>必填</td><td>否</td><td>Browser-accessible S3 origin. Defaults to S3_ENDPOINT; HTTPS except loopback.</td></tr><tr><td><code>S3_BUCKET</code></td><td>saas-files</td><td>否</td><td>Dedicated private application bucket.</td></tr><tr><td><code>S3_REGION</code></td><td>us-east-1</td><td>否</td><td>S3 signing region.</td></tr><tr><td><code>S3_ACCESS_KEY</code></td><td>必填</td><td>是</td><td>Explicit S3 access key; required when S3_ENDPOINT is set.</td></tr><tr><td><code>S3_SECRET_KEY</code></td><td>必填</td><td>是</td><td>Explicit S3 secret; required when enabled, never logged.</td></tr><tr><td><code>FILE_MAX_BYTES</code></td><td>20971520</td><td>否</td><td>File byte limit, verified again on the final object (1..104857600).</td></tr><tr><td><code>UPLOAD_SESSION_SECS</code></td><td>900</td><td>否</td><td>Upload resource/signing lifetime in seconds (1..3600).</td></tr><tr><td><code>DOWNLOAD_URL_SECS</code></td><td>60</td><td>否</td><td>Download capability lifetime in seconds (1..300). Revocation blocks new signing.</td></tr><tr><td><code>WORKER_BIND</code></td><td>127.0.0.1:3001</td><td>否</td><td>Worker health listener IP address and port.</td></tr><tr><td><code>JOB_LEASE_SECS</code></td><td>60</td><td>否</td><td>Job lease lifetime (5..3600 seconds).</td></tr><tr><td><code>JOB_HEARTBEAT_SECS</code></td><td>20</td><td>否</td><td>Lease renewal interval (1..half the lease seconds).</td></tr><tr><td><code>JOB_SHUTDOWN_SECS</code></td><td>10</td><td>否</td><td>Maximum active-work drain before process exit (1..60 seconds).</td></tr><tr><td><code>JOB_MAINTENANCE_SECS</code></td><td>30</td><td>否</td><td>Interval for bounded maintenance scheduling (1..3600 seconds).</td></tr><tr><td><code>REDIS_URL</code></td><td>必填</td><td>是</td><td>Optional redis:// connection URL. Unset disables caching; credentials are never logged.</td></tr><tr><td><code>CACHE_PREFIX</code></td><td>saas</td><td>否</td><td>Deployment cache namespace (1..100 ASCII letters, digits, colon, dash or underscore).</td></tr><tr><td><code>CACHE_TTL_SECS</code></td><td>60</td><td>否</td><td>Text cache TTL in seconds (1..3600). PostgreSQL remains the authorization/version source.</td></tr><tr><td><code>CACHE_BUDGET_MS</code></td><td>100</td><td>否</td><td>Total optional Redis budget per read, including lookup/fill (1..1000 milliseconds).</td></tr><tr><td><code>RATE_LIMIT_ENABLED</code></td><td>true</td><td>否</td><td>Enable registration, authentication and general request policies.</td></tr><tr><td><code>RATE_LIMIT_WINDOW_SECS</code></td><td>60</td><td>否</td><td>Fixed-window duration shared by rate policies (1..3600).</td></tr><tr><td><code>RATE_LIMIT_REGISTRATION</code></td><td>20</td><td>否</td><td>Registration requests per TCP peer/window with Redis (1..1000000).</td></tr><tr><td><code>RATE_LIMIT_REGISTRATION_FALLBACK</code></td><td>5</td><td>否</td><td>Conservative local registration capacity (1..registration capacity).</td></tr><tr><td><code>RATE_LIMIT_AUTHENTICATION</code></td><td>60</td><td>否</td><td>Credential requests per TCP peer/window with Redis (1..1000000).</td></tr><tr><td><code>RATE_LIMIT_AUTHENTICATION_FALLBACK</code></td><td>20</td><td>否</td><td>Conservative local authentication capacity (1..authentication capacity).</td></tr><tr><td><code>RATE_LIMIT_RESOURCE</code></td><td>600</td><td>否</td><td>Other requests per TCP peer/window with Redis (1..1000000); health probes are excluded.</td></tr><tr><td><code>RATE_LIMIT_RESOURCE_FALLBACK</code></td><td>120</td><td>否</td><td>Conservative local resource capacity (1..resource capacity).</td></tr><tr><td><code>RATE_LIMIT_MAX_LOCAL_ENTRIES</code></td><td>4096</td><td>否</td><td>Maximum local peer/policy buckets (1..100000); overflow shares conservative policy windows.</td></tr><tr><td><code>RATE_LIMIT_PREFIX</code></td><td>saas</td><td>否</td><td>Redis limiter namespace, isolated from text cache keys.</td></tr><tr><td><code>RATE_LIMIT_BUDGET_MS</code></td><td>50</td><td>否</td><td>Absolute Redis counter operation deadline (1..1000 ms), then local fallback.</td></tr><tr><td><code>MAIL_SMTP_HOST</code></td><td>必填</td><td>否</td><td>SMTP host. Unset disables password reset delivery; ordinary registration/login remain available.</td></tr><tr><td><code>MAIL_SMTP_PORT</code></td><td>1025</td><td>否</td><td>SMTP port (1..65535); typically 465 wrapper, 587 STARTTLS, 1025 local capture.</td></tr><tr><td><code>MAIL_SMTP_TLS</code></td><td>local</td><td>否</td><td>wrapper, starttls, or local (only loopback/localhost/mailpit).</td></tr><tr><td><code>MAIL_FROM</code></td><td>noreply@example.test</td><td>否</td><td>Validated sender mailbox.</td></tr><tr><td><code>MAIL_SMTP_USERNAME</code></td><td>必填</td><td>是</td><td>Optional SMTP username; requires matching password.</td></tr><tr><td><code>MAIL_SMTP_PASSWORD</code></td><td>必填</td><td>是</td><td>Optional SMTP password; never logged.</td></tr><tr><td><code>MAIL_TIMEOUT_SECS</code></td><td>30</td><td>否</td><td>Whole SMTP attempt deadline, including TLS/DATA/QUIT (1..300 seconds).</td></tr><tr><td><code>MAIL_ENCRYPTION_KEY</code></td><td>必填</td><td>是</td><td>Independent 32-byte hex key for short-lived mail materials; shared by API/Worker, required with SMTP.</td></tr><tr><td><code>MAIL_ENCRYPTION_KEY_VERSION</code></td><td>1</td><td>否</td><td>Current positive key version; drain or expire old materials before rotation.</td></tr><tr><td><code>PASSWORD_RESET_TTL_SECS</code></td><td>1800</td><td>否</td><td>Reset link lifetime (60..3600 seconds); mail material cannot outlive the link.</td></tr><tr><td><code>PASSWORD_RESET_COOLDOWN_SECS</code></td><td>60</td><td>否</td><td>Coalesce repeated active reset requests for one account (1..300 seconds).</td></tr><tr><td><code>EXPORT_JOB_MAX_ATTEMPTS</code></td><td>5</td><td>否</td><td>Finite attempt budget per export execution batch (1..20).</td></tr><tr><td><code>EXPORT_MAX_ATTACHMENTS</code></td><td>100</td><td>否</td><td>Maximum attachments in one document export (0..1000).</td></tr><tr><td><code>EXPORT_MAX_INPUT_BYTES</code></td><td>268435456</td><td>否</td><td>Maximum snapshot Markdown and attachment bytes (1..1073741824).</td></tr><tr><td><code>EXPORT_MAX_OUTPUT_BYTES</code></td><td>285212672</td><td>否</td><td>Maximum ZIP extent, including headers and central directory (1024..1107296256).</td></tr><tr><td><code>EXPORT_RETENTION_SECS</code></td><td>86400</td><td>否</td><td>Export and snapshot lifetime (60..604800 seconds).</td></tr><tr><td><code>EXPORT_TIMEOUT_SECS</code></td><td>120</td><td>否</td><td>Entire export execution budget (1..600 seconds), with cooperative blocking cancellation.</td></tr></tbody></table><p>开发脚本额外读取的 PostgreSQL 端口、Web 代理和教程 URL 见 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/170dd9b4f21f069f557d3db0c238dd66877618b9/.env.example" target="_blank" rel="noreferrer">.env.example</a>；它们不是浏览器可读取的 DATABASE_URL。</p>',4)])])}const E=d(c,[["render",a]]);export{S as __pageData,E as default};
